3	import { createHash } from "node:crypto";
4	
5	import { revalidatePath } from "next/cache";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import { checkRateLimit } from "./rate-limit";
9	import { canAdministerOrg, signInviteToken, verifyInviteToken, INVITE_TTL_HOURS } from "./team-guard";
10	
11	/**
12	 * Teams / Organizations — shared-account server actions.
13	 *
14	 * An Organization has one owner (User "OrgOwner") plus a set of Memberships.
15	 * Every actor is verified to hold a Membership of the required role in the
16	 * target org before any mutation runs, so a hand-crafted request can't touch
17	 * an org the caller doesn't belong to.
18	 *
19	 * WHAT A MEMBERSHIP ACTUALLY GRANTS (be precise — this used to be overstated):
20	 * visibility of the org roster, and, for OWNER/ADMIN, the right to invite,
21	 * re-role and remove members. It grants NOTHING ELSE. Servers, domains,
22	 * volumes, game servers, billing and invoices all remain scoped to the account
23	 * that owns them; no loader or action anywhere joins Membership to a resource.
24	 * The per-member "dashboard areas" control that used to sit on this page has
25	 * been removed rather than left in place: `Membership.areas` was written, echoed
26	 * back as saved, and read by nothing, so an owner who restricted a member to
27	 * Invoices was shown a restriction that did not exist. See lib/team-guard.ts for
28	 * why enforcing it for real is out of this change's reach, and the note rendered
29	 * in components/customer/TeamManager.tsx for what the customer is now told.
30	 *
31	 * CONSENT: `inviteMember` emails an invitation; only `acceptInvite`, run by the
32	 * invitee, creates a Membership. Nothing here can add a person to an org they
33	 * did not agree to join — see lib/team-guard.ts for the full rationale (it is
34	 * what fed the 2FA oracle, QA-PRELAUNCH P0-2).
35	 *
36	 * STILL OUT OF SCOPE: shared billing (org wallet / invoices) and members
37	 * inheriting access to shared servers. Deliberately absent, not half-built.
38	 */
39	
40	const ROLES = ["OWNER", "ADMIN", "MEMBER", "BILLING"] as const;
41	type OrgRole = (typeof ROLES)[number];
42	
43	function isRole(v: string): v is OrgRole {
44	  return (ROLES as readonly string[]).includes(v);
45	}
