55	/**
56	 * Create an organization owned by the current user, plus an OWNER membership
57	 * for the creator. Consumed via `useActionState`.
58	 */
59	export async function createOrg(
60	  _prev: unknown,
61	  formData: FormData,
62	): Promise<{ error?: string; ok?: boolean }> {
63	  const user = await requireUser();
64	  const name = String(formData.get("name") ?? "").trim();
65	  if (name.length < 2 || name.length > 60) {
66	    return { error: "Organization name must be 2–60 characters." };
67	  }
68	
69	  await db.organization.create({
70	    data: {
71	      name,
72	      ownerId: user.id,
73	      members: {
74	        create: { userId: user.id, role: "OWNER" },
75	      },
76	    },
77	  });
78	
79	  await db.auditLog.create({
80	    data: { userId: user.id, action: "org.created", detail: name },
81	  });
82	  revalidatePath("/dashboard/team");
83	  return { ok: true };
84	}
85	
86	/**
87	 * Email an invitation. Only OWNER/ADMIN of the org may invite. **No Membership
88	 * is created here** — the invitee creates it themselves via `acceptInvite`.
89	 *
90	 * Deliberately does NOT look the email up in the User table. The old version
91	 * did, and that single query produced two leaks from one action any signed-in
92	 * customer can call: it answered "does an account exist with this address?"
93	 * (enumeration oracle), and on a hit it created a Membership whose row then
94	 * exposed the invitee's internal `userId` on the team page — the input the
95	 * unauthenticated 2FA oracle needed (QA-PRELAUNCH P0-2). We send the mail and
96	 * learn nothing: the same response comes back whether or not the address has an
97	 * account, and the sender finds out only if the person chooses to accept.
98	 */
99	export async function inviteMember(
100	  orgId: string,
101	  email: string,
102	  role: string,
103	): Promise<{ error?: string; ok?: boolean; message?: string }> {
104	  const user = await requireUser();
105	  const invitedEmail = String(email ?? "").trim().toLowerCase();
106	  if (!invitedEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(invitedEmail)) {
107	    return { error: "Enter a valid email address." };
108	  }
109	  const wantRole = String(role ?? "MEMBER").toUpperCase();
110	  if (!isRole(wantRole) || wantRole === "OWNER") {
111	    // OWNER is assigned only at creation / ownership transfer, never via invite.
112	    return { error: "Choose a role of ADMIN, MEMBER or BILLING." };
113	  }
114	
115	  const actor = await actorMembership(orgId, user.id);
116	  if (!actor || !canAdministerOrg(actor.role)) {
117	    return { error: "You don't have permission to invite members to this organization." };
118	  }
119	
