229	 * Re-checks at redemption time, because the token carries no server-side state:
230	 * the org still exists, the inviter still administers it, the role is still
231	 * sane, and the token's address matches the signed-in account.
232	 */
233	export async function acceptInvite(
234	  token: string,
235	): Promise<{ error?: string; ok?: boolean; orgName?: string; alreadyMember?: boolean }> {
236	  const user = await requireUser();
237	
238	  const claims = await verifyInviteToken(String(token ?? ""));
239	  /* A cancelled invite must stop working. Checked HERE, against the record
240	     written when it was sent — without this, "revoke" would be a button that
241	     changed a row and nothing else, and the signed token would keep letting
242	     someone in for its full seven days. */
243	  if (claims) {
244	    const rec = await db.orgInvite.findUnique({
245	      where: { orgId_email: { orgId: claims.orgId, email: claims.email } },
246	      select: { revokedAt: true },
247	    }).catch(() => null);
248	    if (rec?.revokedAt) {
249	      return { error: "This invitation has been cancelled. Ask for a new one." };
250	    }
251	  }
252	  if (!claims) {
253	    return {
254	      error: "This invitation link is invalid or has expired. Ask the organization owner to send a new one.",
255	    };
256	  }
257	
258	  // Bound to one address, so a forwarded link can't be redeemed by the recipient.
259	  if (claims.email !== user.email.trim().toLowerCase()) {
260	    return {
261	      error: "This invitation was sent to a different email address. Sign in as that account to accept it.",
262	    };
263	  }
264	
265	  if (!isRole(claims.role) || claims.role === "OWNER") {
266	    return { error: "This invitation carries an invalid role and can't be accepted." };
267	  }
268	
269	  const org = await db.organization.findUnique({
270	    where: { id: claims.orgId },
271	    select: { id: true, name: true },
272	  });
273	  if (!org) return { error: "That organization no longer exists." };
274	
275	  // Revocation, given there is no invitation row to delete: an outstanding
276	  // invitation dies the moment its sender loses the right to have sent it.
277	  const inviter = await actorMembership(org.id, claims.invitedBy);
278	  if (!inviter || !canAdministerOrg(inviter.role)) {
279	    return {
280	      error: "Whoever invited you no longer administers this organization, so the invitation is no longer valid.",
281	    };
282	  }
283	
284	  const existing = await actorMembership(org.id, user.id);
285	  if (existing) {
286	    return { ok: true, orgName: org.name, alreadyMember: true };
287	  }
288	
289	  await db.membership.create({
290	    data: { orgId: org.id, userId: user.id, role: claims.role },
291	  });
292	  await db.auditLog.create({
293	    data: {
294	      userId: user.id,
295	      action: "org.invite_accepted",
296	      detail: `${org.name} → ${claims.role}`,
297	    },
298	  });
299	  revalidatePath("/dashboard/team");
300	  return { ok: true, orgName: org.name };
301	}
