303	/**
304	 * Change a member's role. Only OWNER/ADMIN act. The owner's own membership is
305	 * pinned to OWNER and cannot be downgraded here.
306	 *
307	 * Takes a `membershipId`, not a `userId`: the client is never sent co-members'
308	 * user ids any more (see app/dashboard/team/page.tsx), so it has none to send
309	 * back. The org is derived from the membership rather than trusted from the
310	 * caller, which also removes the chance of a mismatched (orgId, userId) pair.
311	 */
312	export async function updateMemberRole(
313	  membershipId: string,
314	  role: string,
315	): Promise<{ error?: string; ok?: boolean }> {
316	  const user = await requireUser();
317	  const wantRole = String(role ?? "").toUpperCase();
318	  if (!isRole(wantRole) || wantRole === "OWNER") {
319	    return { error: "Pick a role of ADMIN, MEMBER or BILLING." };
320	  }
321	
322	  const target = await db.membership.findUnique({ where: { id: String(membershipId ?? "") } });
323	  if (!target) return { error: "That person isn't a member of this organization." };
324	
325	  const actor = await actorMembership(target.orgId, user.id);
326	  if (!actor || !canAdministerOrg(actor.role)) {
327	    return { error: "You don't have permission to change roles in this organization." };
328	  }
329	
330	  const org = await db.organization.findUnique({
331	    where: { id: target.orgId },
332	    select: { ownerId: true },
333	  });
334	  if (!org) return { error: "Organization not found." };
335	  if (target.userId === org.ownerId || target.role === "OWNER") {
336	    return { error: "The organization owner's role can't be changed." };
337	  }
338	
339	  await db.membership.update({
340	    where: { id: target.id },
341	    data: { role: wantRole },
342	  });
343	  await db.auditLog.create({
344	    data: {
345	      userId: user.id,
346	      action: "org.member_role_changed",
347	      detail: `${target.userId} → ${wantRole}`,
348	    },
349	  });
350	  revalidatePath("/dashboard/team");
351	  return { ok: true };
352	}
