412	/** Cancel an outstanding invitation. Gated by the same `canAdministerOrg` that
413	 *  authorises sending one — anyone who may invite may un-invite. The token is
414	 *  not revoked (it cannot be, it is stateless and already sent); `acceptInvite`
415	 *  checks this row and refuses, which is what makes the button mean something. */
416	export async function revokeInvite(orgId: string, email: string): Promise<{ ok?: boolean; error?: string }> {
417	  const user = await requireUser();
418	  /* Same two-step the invite path uses: resolve the caller's membership in THIS
419	     org, then ask whether that role may administer it. `canAdministerOrg` takes
420	     a role, not a user — it is the single definition of the permission and both
421	     paths go through it. */
422	  const actor = await actorMembership(orgId, user.id);
423	  if (!actor || !canAdministerOrg(actor.role)) {
424	    return { error: "You don't have permission to manage invitations for this organization." };
425	  }
426	  const r = await db.orgInvite.updateMany({
427	    where: { orgId, email: email.trim().toLowerCase(), acceptedAt: null, revokedAt: null },
428	    data: { revokedAt: new Date() },
429	  });
430	  if (r.count === 0) return { error: "That invitation has already been accepted or cancelled." };
431	  revalidatePath("/dashboard/team");
432	  return { ok: true };
433	}
