     1	import { db } from "../lib/db";
     2	import { recordSample } from "../lib/uptime";
     3	import { vmStatus } from "../lib/proxmox";
     4	
     5	/* The availability sampler.
     6	 *
     7	 * Every sweep asks Proxmox whether each provisioned VM is running and folds the
     8	 * answer into that server's daily counters. The percentage the dashboard shows
     9	 * is built entirely from these samples.
    10	 *
    11	 * Cadence is a trade: every 5 minutes over 30 days is ~8,600 observations per
    12	 * server, which is enough resolution that a single short outage moves the
    13	 * figure, without hammering the Proxmox API. */
    14	
    15	export const UPTIME_SWEEP_MS = 5 * 60_000;
    16	
    17	/** Statuses where the server is not expected to be up, so sampling it would
    18	 *  record a false outage. A stopped VM is the customer's choice, not downtime;
    19	 *  a provisioning one has not started existing yet. */
    20	const NOT_MEASURED = new Set(["PENDING", "PROVISIONING", "REINSTALLING", "DELETING", "STOPPED", "ERROR"]);
    21	
    22	export async function sweepUptime(): Promise<{ sampled: number; up: number; failed: number }> {
    23	  const servers = await db.server.findMany({
    24	    where: { vmid: { not: null }, status: { notIn: [...NOT_MEASURED] as never } },
    25	    select: { id: true, vmid: true },
    26	  });
    27	
    28	  let up = 0;
    29	  let sampled = 0;
    30	  let failed = 0;
    31	
    32	  for (const s of servers) {
    33	    if (s.vmid == null) continue;
    34	    try {
    35	      const st = await vmStatus(s.vmid);
    36	      const isUp = st?.status === "running";
    37	      await recordSample(s.id, isUp);
    38	      sampled++;
    39	      if (isUp) up++;
    40	    } catch {
    41	      // An API error is OUR blind spot, not the customer's outage. Recording a
    42	      // down sample here would blame the customer's server for our inability to
    43	      // reach the hypervisor — so the sample is dropped and the day's `total`
    44	      // simply does not grow.
    45	      failed++;
    46	    }
    47	  }
    48	  return { sampled, up, failed };
    49	}

