import type { ServiceRow } from "@/lib/nx/services";

/** What the card's picture is rendered at, so an upload is stored at the size
 *  it will actually be shown rather than at whatever the camera produced. */
const OUT_W = 1440;
const OUT_H = 450;

/**
 * Downscale and re-encode in the browser before uploading.
 *
 * Two reasons this happens client-side: a phone photo is several megabytes of
 * detail this card will never show, and `sharp` is only a transitive dependency
 * here — there is no image pipeline on the server to rely on. The server still
 * validates the real bytes it receives; this only keeps the upload small.
 */
async function toCardImage(file: File): Promise<File> {
  const bitmap = await createImageBitmap(file);
  const canvas = document.createElement("canvas");
  canvas.width = OUT_W;
  canvas.height = OUT_H;
  const ctx = canvas.getContext("2d");
  if (!ctx) return file;

  // Cover: fill the frame, crop the overflow, never letterbox or squash.
  const scale = Math.max(OUT_W / bitmap.width, OUT_H / bitmap.height);
  const w = bitmap.width * scale;
  const h = bitmap.height * scale;
  ctx.imageSmoothingQuality = "high";
  ctx.drawImage(bitmap, (OUT_W - w) / 2, (OUT_H - h) / 2, w, h);
  bitmap.close();

  const blob = await new Promise<Blob | null>((res) => canvas.toBlob(res, "image/webp", 0.88));
  if (!blob) return file;
  return new File([blob], "preview.webp", { type: "image/webp" });
}

